using System;
using System.Collections.Generic;
using System.Globalization;

namespace Quack.Core
{
    /// <summary>One inspected egg. Raw measurements are in physical units (g, mm, mm).</summary>
    public sealed class Egg
    {
        public int Id;
        public double[] Raw;     // [mass_g, length_mm, width_mm]
        public int Label;        // 1 = JUMBO carton, 0 = STANDARD carton
        public bool IsTest;      // withheld from training
    }

    /// <summary>
    /// The fictional, synthetic inspector dataset (generated by tools/gen_eggs.py).
    /// </summary>
    public sealed class EggDataset
    {
        public static readonly string[] FeatureNames = { "Mass", "Length", "Width" };
        public static readonly string[] FeatureUnits = { "g", "mm", "mm" };
        public static readonly string[] ClassNames = { "STANDARD", "JUMBO" };
        public const int FeatureCount = 3;

        public readonly List<Egg> All = new List<Egg>();
        public readonly List<Egg> Train = new List<Egg>();
        public readonly List<Egg> Test = new List<Egg>();

        public static EggDataset ParseCsv(string csv)
        {
            var ds = new EggDataset();
            var lines = csv.Replace("\r", "").Split('\n');
            for (int i = 1; i < lines.Length; i++)
            {
                var line = lines[i].Trim();
                if (line.Length == 0) continue;
                var c = line.Split(',');
                if (c.Length != 6) throw new FormatException($"eggs.csv line {i + 1}: expected 6 columns");
                var egg = new Egg
                {
                    Id = int.Parse(c[0], CultureInfo.InvariantCulture),
                    Raw = new[]
                    {
                        double.Parse(c[1], CultureInfo.InvariantCulture),
                        double.Parse(c[2], CultureInfo.InvariantCulture),
                        double.Parse(c[3], CultureInfo.InvariantCulture),
                    },
                    Label = int.Parse(c[4], CultureInfo.InvariantCulture),
                    IsTest = c[5] == "test",
                };
                if (egg.Label != 0 && egg.Label != 1) throw new FormatException($"eggs.csv line {i + 1}: label must be 0/1");
                ds.All.Add(egg);
                (egg.IsTest ? ds.Test : ds.Train).Add(egg);
            }
            return ds;
        }
    }
}
